//! Log entry data model (Part D6). The desktop shell captures these into a
//! bounded ring buffer the Dashboard's System Logs panel reads over IPC. Kept
//! here (core) so the TypeScript binding is generated by ts-rs like every other
//! IPC type — single source of truth, no hand-duplication.

use serde::Serialize;
use ts_rs::TS;

/// One captured log line surfaced in the System Logs panel.
#[derive(Clone, Debug, Serialize, TS)]
#[ts(export)]
pub struct LogEntry {
    /// Monotonic id (unique within a session).
    pub id: u64,
    /// Epoch milliseconds.
    pub ts: u64,
    /// "error" | "warn" | "info" | "debug" | "trace".
    pub level: String,
    /// Origin subsystem, e.g. "ipc", "ai", "toolchain", "storage".
    pub source: String,
    pub message: String,
    /// Optional beginner-friendly context (hint / help article).
    pub detail: Option<String>,
}
